mapper.select:
SELECT id,
       issue_no,
       status,
       factory,
       area,
       line,
       process,
       category_l1_id,
       category_l2_id,
       description,
       current_handler_emp_no,
       current_handler_emp_name,
       submit_time,
       CASE
         WHEN status <> 'CLOSED' AND submit_time < DATE_SUB(NOW(), INTERVAL 3 DAY) THEN 1
         ELSE 0
       END AS overdue
FROM cps_issue
WHERE (#{tab} != 'todo' OR (current_handler_emp_no = #{empNo} AND status <> 'CLOSED'))
  AND (#{tab} != 'created' OR creator_emp_no = #{empNo})
  AND (#{tab} != 'related' OR (
        creator_emp_no = #{empNo}
        OR current_handler_emp_no = #{empNo}
        OR feedback_emp_no = #{empNo}
        OR responsible_emp_no = #{empNo}
        OR proof_emp_no = #{empNo}
        OR reviewer_emp_no = #{empNo}
        OR EXISTS (
          SELECT 1
          FROM cps_issue_flow_log
          WHERE cps_issue_flow_log.issue_id = cps_issue.id
            AND cps_issue_flow_log.operator_emp_no = #{empNo}
        )
      ))
  AND (#{tab} != 'closed' OR (status = 'CLOSED' AND (
        creator_emp_no = #{empNo}
        OR current_handler_emp_no = #{empNo}
        OR feedback_emp_no = #{empNo}
        OR responsible_emp_no = #{empNo}
        OR proof_emp_no = #{empNo}
        OR reviewer_emp_no = #{empNo}
        OR EXISTS (
          SELECT 1
          FROM cps_issue_flow_log
          WHERE cps_issue_flow_log.issue_id = cps_issue.id
            AND cps_issue_flow_log.operator_emp_no = #{empNo}
        )
      )))
ORDER BY submit_time DESC
LIMIT #{limit} OFFSET #{offset}
